define({
  inputs: { items: 'array', userId: 'string' },
  outputs: { listText: 'string' },
  run: function(inputs, outputs) {
    var items = inputs.items || [];
    var uid = inputs.userId;
    var filtered = items.filter(function(a){ return a.userId === uid; });
    filtered.sort(function(a,b){ return new Date(b.savedAt) - new Date(a.savedAt); });
    var lines = filtered.map(function(a){
      var d = new Date(a.savedAt);
      var dateStr = d.toLocaleDateString();
      return a.title + '  —  saved ' + dateStr;
    });
    outputs.listText = lines.length ? lines.join('\n\n') : 'No saved articles yet.';
  }
});
